"""Data-driven one-shot emote playback for policy command vectors.

The player understands ``darkwing_emote_control_v1`` JSON files.  It converts
absolute head/neck joint angles and trunk-angle offsets into the command space
advertised by an ONNX policy, while leaving non-policy show channels (currently
``ears``) available to the runtime through callbacks.

Design goals:
  * No hard-coded command indices.
  * Policy-specific angle zeroes come from the exported initial joint pose.
  * Policy-specific limits/ranges come from exported metadata.
  * Every policy pose channel is relative to the live joystick command each tick.
  * Relative pose composition happens in physical degrees before normalization.
  * Base locomotion X/Y/yaw remains owned by the live joystick.
  * Clips are discovered by name from one or more ``emotes`` directories.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, Iterable, Mapping, Optional, Sequence, Tuple

import json
import math
import os
import re


SUPPORTED_FORMAT = "darkwing_emote_control_v1"

# The authored body channels use animation-facing semantics shared with
# Duckmation: body_lean is trunk pitch, body_tilt is trunk roll, and
# body_twist is trunk yaw.  The policy's pitch command retains DuckDrive's
# established sign inversion; roll and yaw preserve the authored sign.  The
# supplied shake_it_off clip intentionally gives body_twist and head_yaw the
# same authored value: the robot's trunk/head yaw axes make those commands
# counter-rotate physically.  Negating only body_twist breaks that pairing.
DEFAULT_TRUNK_CHANNELS: Dict[str, Tuple[str, str, float]] = {
    "body_lean": ("trunk_pitch_cmd", "pitch", -1.0),
    "body_tilt": ("trunk_roll_cmd", "roll", +1.0),
    "body_twist": ("trunk_yaw_cmd", "yaw", +1.0),
    # Friendly aliases for future files.
    "body_pitch": ("trunk_pitch_cmd", "pitch", -1.0),
    "body_roll": ("trunk_roll_cmd", "roll", +1.0),
    "body_yaw": ("trunk_yaw_cmd", "yaw", +1.0),
    "trunk_pitch": ("trunk_pitch_cmd", "pitch", +1.0),
    "trunk_roll": ("trunk_roll_cmd", "roll", +1.0),
    "trunk_yaw": ("trunk_yaw_cmd", "yaw", +1.0),
}

ABSOLUTE_HEAD_CHANNELS = (
    "neck_pitch",
    "head_pitch",
    "head_yaw",
    "head_roll",
)

SHOW_CHANNELS = {
    "ears",
    "left_ear",
    "right_ear",
    "left_antenna",
    "right_antenna",
}

# Locomotion remains owned by DuckDrive/joystick synthesis while an emote is
# active.  These channels are never generated, zeroed, or restored by the
# animation overlay, even if a future JSON clip names them directly.
PASSTHROUGH_COMMAND_CHANNELS = frozenset(
    {
        "lin_vel_x",
        "lin_vel_y",
        "ang_vel_yaw",
    }
)

_HEIGHT_PATH_PATTERNS = (
    re.compile(r"walk_com_height(-?\d+(?:\.\d+)?)", re.IGNORECASE),
    re.compile(r"(?:^|[/_-])com_height(-?\d+(?:\.\d+)?)", re.IGNORECASE),
    re.compile(r"(?:^|[/_-])root_height(-?\d+(?:\.\d+)?)", re.IGNORECASE),
)


def _clamp(value: float, lo: float, hi: float) -> float:
    if hi < lo:
        lo, hi = hi, lo
    return lo if value < lo else hi if value > hi else value


def _as_mapping(value: Any) -> Mapping[str, Any]:
    return value if isinstance(value, Mapping) else {}


def _as_numeric_pair(
    value: Any,
    *,
    sort: bool = False,
    require_span: bool = False,
) -> Optional[Tuple[float, float]]:
    """Parse a two-number sequence while optionally preserving its order.

    Ranges are sorted and require a non-zero span.  Direction vectors are not
    ranges: ``[1, -1]`` and ``[1, 1]`` must retain their authored order and
    equal values are valid.
    """
    if not (
        isinstance(value, Sequence)
        and not isinstance(value, (str, bytes, bytearray))
        and len(value) == 2
    ):
        return None
    try:
        first = float(value[0])
        second = float(value[1])
    except (TypeError, ValueError):
        return None
    if not (math.isfinite(first) and math.isfinite(second)):
        return None
    if require_span and abs(second - first) <= 1e-12:
        return None
    if sort and second < first:
        first, second = second, first
    return first, second


def _as_float_pair(value: Any) -> Optional[Tuple[float, float]]:
    """Parse a numeric range, returning it in increasing order."""
    return _as_numeric_pair(value, sort=True, require_span=True)


def _iter_nested(value: Any) -> Iterable[Any]:
    """Yield nested values without depending on a specific metadata schema."""
    yield value
    if isinstance(value, Mapping):
        for child in value.values():
            yield from _iter_nested(child)
    elif isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        for child in value:
            yield from _iter_nested(child)


def _find_mapping_with_key(value: Any, key: str) -> Optional[Mapping[str, Any]]:
    if isinstance(value, Mapping):
        if key in value:
            return value
        for child in value.values():
            found = _find_mapping_with_key(child, key)
            if found is not None:
                return found
    elif isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        for child in value:
            found = _find_mapping_with_key(child, key)
            if found is not None:
                return found
    return None


def _find_first_value(value: Any, keys: Sequence[str]) -> Any:
    if isinstance(value, Mapping):
        for key in keys:
            if key in value:
                return value[key]
        for child in value.values():
            found = _find_first_value(child, keys)
            if found is not None:
                return found
    elif isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        for child in value:
            found = _find_first_value(child, keys)
            if found is not None:
                return found
    return None


def _zero_centered_map(
    value: float,
    physical_range: Tuple[float, float],
    command_range: Tuple[float, float],
) -> float:
    """Map a signed physical offset through asymmetric ranges with 0 -> 0."""
    phys_lo, phys_hi = physical_range
    cmd_lo, cmd_hi = command_range
    value = float(value)

    if value >= 0.0:
        denom = max(abs(float(phys_hi)), 1e-12)
        ratio = value / denom
        out = ratio * (cmd_hi if cmd_hi > 0.0 else abs(cmd_hi - cmd_lo))
    else:
        denom = max(abs(float(phys_lo)), 1e-12)
        ratio = abs(value) / denom
        out = -ratio * (abs(cmd_lo) if cmd_lo < 0.0 else abs(cmd_hi - cmd_lo))

    return _clamp(out, cmd_lo, cmd_hi)


def _zero_centered_command_to_physical(
    command: float,
    physical_range: Tuple[float, float],
    command_range: Tuple[float, float],
) -> float:
    """Invert :func:`_zero_centered_map` for physical-space composition."""
    phys_lo, phys_hi = physical_range
    cmd_lo, cmd_hi = command_range
    command = _clamp(float(command), cmd_lo, cmd_hi)

    if command >= 0.0:
        scale = cmd_hi if cmd_hi > 0.0 else abs(cmd_hi - cmd_lo)
        if scale <= 1e-12:
            return 0.0
        out = (command / scale) * float(phys_hi)
    else:
        scale = abs(cmd_lo) if cmd_lo < 0.0 else abs(cmd_hi - cmd_lo)
        if scale <= 1e-12:
            return 0.0
        out = -(abs(command) / scale) * abs(float(phys_lo))

    return _clamp(out, phys_lo, phys_hi)


def _absolute_to_zero_centered_command(
    value: float,
    neutral: float,
    physical_limits: Tuple[float, float],
    command_range: Tuple[float, float],
) -> float:
    """Map an absolute joint angle so the exported initial pose is command 0."""
    lo, hi = physical_limits
    cmd_lo, cmd_hi = command_range
    value = _clamp(float(value), lo, hi)
    neutral = _clamp(float(neutral), lo, hi)

    if value >= neutral:
        denom = hi - neutral
        if denom <= 1e-12:
            return _clamp(0.0, cmd_lo, cmd_hi)
        ratio = (value - neutral) / denom
        out = ratio * (cmd_hi if cmd_hi > 0.0 else abs(cmd_hi - cmd_lo))
    else:
        denom = neutral - lo
        if denom <= 1e-12:
            return _clamp(0.0, cmd_lo, cmd_hi)
        ratio = (neutral - value) / denom
        out = -ratio * (abs(cmd_lo) if cmd_lo < 0.0 else abs(cmd_hi - cmd_lo))

    return _clamp(out, cmd_lo, cmd_hi)


def _zero_centered_command_to_absolute(
    command: float,
    neutral: float,
    physical_limits: Tuple[float, float],
    command_range: Tuple[float, float],
) -> float:
    """Invert the head/neck mapping to recover the commanded physical angle."""
    lo, hi = physical_limits
    cmd_lo, cmd_hi = command_range
    neutral = _clamp(float(neutral), lo, hi)
    command = _clamp(float(command), cmd_lo, cmd_hi)

    if command >= 0.0:
        scale = cmd_hi if cmd_hi > 0.0 else abs(cmd_hi - cmd_lo)
        if scale <= 1e-12:
            return neutral
        out = neutral + (command / scale) * (hi - neutral)
    else:
        scale = abs(cmd_lo) if cmd_lo < 0.0 else abs(cmd_hi - cmd_lo)
        if scale <= 1e-12:
            return neutral
        out = neutral - (abs(command) / scale) * (neutral - lo)

    return _clamp(out, lo, hi)


@dataclass(frozen=True)
class EmoteClip:
    name: str
    path: Path
    rate_hz: float
    channels: Tuple[str, ...]
    frames: Tuple[Tuple[float, ...], ...]
    units: Mapping[str, Any]
    whole_sequence: Mapping[str, Any]
    playback: Mapping[str, Any]
    declared_duration_s: Optional[float]

    @property
    def duration_s(self) -> float:
        # In this format each frame occupies one 1/rate interval.  The supplied
        # files use duration == frame_count / rate_hz.
        return float(len(self.frames)) / float(self.rate_hz)

    @property
    def feet_planted(self) -> bool:
        return bool(self.whole_sequence.get("feet_planted", False))

    def channel_range(self, name: str) -> Optional[Tuple[float, float]]:
        """Return the authored min/max for one channel."""
        try:
            index = self.channels.index(str(name))
        except ValueError:
            return None
        values = [float(frame[index]) for frame in self.frames]
        if not values:
            return None
        return min(values), max(values)

    def sample(self, elapsed_s: float, *, interpolate: bool = True) -> Tuple[int, Tuple[float, ...]]:
        """Return (authored frame index, sampled channel values)."""
        if not self.frames:
            raise RuntimeError(f"Emote {self.name!r} has no frames")

        t = _clamp(float(elapsed_s), 0.0, max(0.0, self.duration_s - 1e-12))
        pos = t * float(self.rate_hz)
        i0 = min(int(math.floor(pos)), len(self.frames) - 1)
        if (not interpolate) or i0 >= len(self.frames) - 1:
            return i0, self.frames[i0]

        frac = pos - float(i0)
        if frac <= 1e-12:
            return i0, self.frames[i0]

        a = self.frames[i0]
        b = self.frames[i0 + 1]
        values = tuple((1.0 - frac) * av + frac * bv for av, bv in zip(a, b))
        return i0, values


@dataclass(frozen=True)
class EmoteSample:
    name: str
    frame_index: int
    elapsed_s: float
    command_values: Mapping[int, float]
    show_values: Mapping[str, float]
    feet_planted: bool


class PolicyCommandMapper:
    """Convert authored emote channels into one policy's command space."""

    def __init__(
        self,
        policy: Any,
        *,
        height_range_cm: Optional[float] = None,
        trunk_channel_signs: Optional[Mapping[str, float]] = None,
        debug: bool = False,
    ):
        self.policy = policy
        self.debug = bool(debug)
        self.info = _as_mapping(getattr(policy, "info", {}))
        self.config = _as_mapping(getattr(policy, "config", self.info.get(".Config", {})))

        raw_index = getattr(policy, "command_index", {})
        self.command_index: Dict[str, int] = {
            str(k): int(v) for k, v in _as_mapping(raw_index).items()
        }

        self.command_ranges = self._resolve_command_ranges()
        self.joint_neutral_rad = self._resolve_joint_neutral_rad()
        self.joint_limits_rad = self._resolve_joint_limits_rad()
        self.trunk_ranges_deg = self._resolve_trunk_ranges_deg()
        self.trunk_directions = self._resolve_trunk_directions()

        self.trunk_channels = dict(DEFAULT_TRUNK_CHANNELS)
        if trunk_channel_signs:
            for channel, raw_sign in trunk_channel_signs.items():
                if channel not in self.trunk_channels:
                    continue
                try:
                    sign = float(raw_sign)
                except (TypeError, ValueError):
                    continue
                command_name, axis, _old_sign = self.trunk_channels[channel]
                self.trunk_channels[channel] = (command_name, axis, sign)

        self.height_range_cm = self._resolve_height_range_cm(height_range_cm)
        self.height_cm_per_command_unit = self._resolve_height_cm_per_command_unit()
        self._warned: set[str] = set()

    # ------------------------------------------------------------------
    # Metadata resolution
    # ------------------------------------------------------------------

    def _resolve_command_ranges(self) -> Dict[str, Tuple[float, float]]:
        candidates = []
        for key in ("CommandRanges", ".CommandRanges"):
            value = self.info.get(key)
            if isinstance(value, Mapping):
                candidates.append(value)

        norm = self.info.get("CommandNormalization")
        if isinstance(norm, Mapping):
            value = norm.get("command_ranges")
            if isinstance(value, Mapping):
                candidates.append(value)

        for root in (self.config, self.info):
            found = _find_first_value(root, ("command_ranges",))
            if isinstance(found, Mapping):
                candidates.append(found)

        out: Dict[str, Tuple[float, float]] = {}
        for mapping in candidates:
            for name, value in mapping.items():
                pair = _as_float_pair(value)
                if pair is not None and str(name) not in out:
                    out[str(name)] = pair

        for name in self.command_index:
            out.setdefault(name, (-1.0, 1.0))
        return out

    def _resolve_joint_neutral_rad(self) -> Dict[str, float]:
        joints = [str(x) for x in getattr(self.policy, "joints", [])]

        def pose_vector(value: Any) -> Dict[str, float]:
            if not (
                joints
                and isinstance(value, Sequence)
                and not isinstance(value, (str, bytes, bytearray))
                and len(value) == len(joints)
            ):
                return {}
            try:
                return {name: float(raw) for name, raw in zip(joints, value)}
            except (TypeError, ValueError):
                return {}

        # The exported joint pose / robot init-state is the authoritative
        # command-zero reference.  Action pose/offset are compatibility
        # fallbacks for older policies that did not export a joint pose.
        for pose in (
            self.info.get(".InitialJointPose"),
            getattr(self.policy, "initial_joint_pose", None),
        ):
            out = pose_vector(pose)
            if out:
                return out

        # Full metadata carries robot.init_state.joint_pos as a mapping.
        for root in (self.info, self.config):
            holder = _find_mapping_with_key(root, "joint_pos")
            if holder is None:
                continue
            joint_pos = holder.get("joint_pos")
            if not isinstance(joint_pos, Mapping):
                continue
            out: Dict[str, float] = {}
            for name, value in joint_pos.items():
                try:
                    out[str(name)] = float(value)
                except (TypeError, ValueError):
                    continue
            if out:
                return out

        for pose in (
            getattr(self.policy, "initial_action_pose", None),
            self.info.get(".InitialActionPose"),
            self.info.get(".ActionOffset"),
        ):
            out = pose_vector(pose)
            if out:
                return out
        return {}

    def _resolve_joint_limits_rad(self) -> Dict[str, Tuple[float, float]]:
        out: Dict[str, Tuple[float, float]] = {}
        for root in (self.config, self.info):
            value = _find_first_value(root, ("head_joint_limits", "joint_command_limits"))
            if not isinstance(value, Mapping):
                continue
            for name, limits in value.items():
                pair = _as_float_pair(limits)
                if pair is not None:
                    out.setdefault(str(name), pair)
        return out

    def _resolve_trunk_ranges_deg(self) -> Dict[str, Tuple[float, float]]:
        out: Dict[str, Tuple[float, float]] = {}
        for axis in ("pitch", "roll", "yaw"):
            value = None
            for root in (self.config, self.info):
                value = _find_first_value(root, (f"trunk_{axis}_range_deg",))
                if value is not None:
                    break
            pair = _as_float_pair(value)
            if pair is not None:
                out[axis] = pair
        return out

    def _resolve_trunk_directions(self) -> Dict[str, Tuple[float, float]]:
        # Retained for diagnostics and future policy adapters.  These values are
        # commonly per-side kinematic directions rather than command signs, so
        # the v1 body-channel coordinate transform remains explicit above.
        out: Dict[str, Tuple[float, float]] = {}
        for axis in ("pitch", "roll", "yaw"):
            value = None
            for root in (self.config, self.info):
                value = _find_first_value(root, (f"trunk_{axis}_direction",))
                if value is not None:
                    break
            pair = _as_numeric_pair(value, sort=False, require_span=False)
            if pair is not None:
                out[axis] = pair
        return out

    def _resolve_height_range_cm(self, explicit: Optional[float]) -> Optional[float]:
        if explicit is not None:
            try:
                value = abs(float(explicit))
            except (TypeError, ValueError):
                value = 0.0
            if value > 1e-9 and math.isfinite(value):
                return value

        # Prefer an explicit physical range when a future exporter provides it.
        for root in (self.config, self.info):
            raw = _find_first_value(
                root,
                (
                    "height_range_cm",
                    "body_height_range_cm",
                    "reference_height_range_cm",
                    "com_height_range_cm",
                ),
            )
            pair = _as_float_pair(raw)
            if pair is not None:
                span = abs(pair[1] - pair[0])
                if span > 1e-9:
                    return span
            try:
                scalar = abs(float(raw)) if raw is not None else 0.0
            except (TypeError, ValueError):
                scalar = 0.0
            if scalar > 1e-9:
                return scalar

            raw_m = _find_first_value(
                root,
                (
                    "height_range_m",
                    "body_height_range_m",
                    "reference_height_range_m",
                    "com_height_range_m",
                    "root_height_range_m",
                ),
            )
            pair_m = _as_float_pair(raw_m)
            if pair_m is not None:
                span_cm = abs(pair_m[1] - pair_m[0]) * 100.0
                if span_cm > 1e-9:
                    return span_cm

        # The supplied policy exports reference paths such as
        # walk_com_height0.24 ... walk_com_height0.33.  Recover the physical
        # span without tying the player to a particular reference count.
        heights_m = []
        for node in _iter_nested(self.info):
            if not isinstance(node, str):
                continue
            for pattern in _HEIGHT_PATH_PATTERNS:
                match = pattern.search(node)
                if match:
                    try:
                        heights_m.append(float(match.group(1)))
                    except (TypeError, ValueError):
                        pass
                    break
        if len(heights_m) >= 2:
            span_cm = (max(heights_m) - min(heights_m)) * 100.0
            if span_cm > 1e-9:
                return span_cm
        return None

    def _resolve_height_cm_per_command_unit(self) -> Optional[float]:
        if self.height_range_cm is None:
            return None
        cmd_range = self.command_ranges.get("height", (-1.0, 1.0))
        span = abs(float(cmd_range[1]) - float(cmd_range[0]))
        if span <= 1e-12:
            return None
        return float(self.height_range_cm) / span

    # ------------------------------------------------------------------
    # Channel conversion
    # ------------------------------------------------------------------

    def command_range(self, name: str) -> Tuple[float, float]:
        return self.command_ranges.get(str(name), (-1.0, 1.0))

    def _warn_once(self, key: str, message: str) -> None:
        if key in self._warned:
            return
        self._warned.add(key)
        if self.debug:
            print(f"[emote] {message}")

    def map_absolute_joint_deg(
        self,
        name: str,
        value_deg: float,
        *,
        zero_command: Optional[float] = None,
    ) -> Optional[Tuple[int, float]]:
        """Map one authored absolute angle, optionally relative to a live pose.

        The source format stores head/neck as absolute servo degrees.  Their
        animation offset is therefore ``authored_angle - exported_neutral``.
        When ``zero_command`` is supplied, that physical offset is added to the
        current joystick-commanded angle before the result is normalized again.
        This both keeps an already-turned head turned when a frame contains
        neutral yaw and lets the operator keep moving the head during playback.
        """
        idx = self.command_index.get(name)
        if idx is None:
            return None
        neutral = self.joint_neutral_rad.get(name)
        limits = self.joint_limits_rad.get(name)
        if neutral is None or limits is None:
            self._warn_once(
                f"joint:{name}",
                f"ignoring {name!r}: initial pose or joint limits are missing from policy metadata",
            )
            return None

        value_rad = _clamp(math.radians(float(value_deg)), limits[0], limits[1])
        target_rad = value_rad
        if zero_command is not None:
            current_rad = _zero_centered_command_to_absolute(
                float(zero_command),
                neutral,
                limits,
                self.command_range(name),
            )
            target_rad = current_rad + (value_rad - neutral)

        command = _absolute_to_zero_centered_command(
            target_rad,
            neutral,
            limits,
            self.command_range(name),
        )
        return idx, command

    def map_trunk_offset_deg(
        self,
        channel: str,
        value_deg: float,
        *,
        zero_command: float = 0.0,
    ) -> Optional[Tuple[int, float]]:
        """Add an authored trunk offset to the current physical posture."""
        mapped = self.map_trunk_offset_deg_with_applied(
            channel,
            value_deg,
            zero_command=zero_command,
        )
        if mapped is None:
            return None
        return int(mapped[0]), float(mapped[1])

    def map_trunk_offset_deg_with_applied(
        self,
        channel: str,
        value_deg: float,
        *,
        zero_command: float = 0.0,
    ) -> Optional[Tuple[int, float, float]]:
        """Map a trunk offset and report the physical offset actually applied.

        The third return value is useful for linked animation channels.  It is
        the post-clamp physical trunk delta from the live joystick pose, not
        merely the requested offset.  A paired head counter-rotation can then
        follow the trunk exactly even when the operator starts near a limit.
        """
        spec = self.trunk_channels.get(channel)
        if spec is None:
            return None
        command_name, axis, authored_to_physical_sign = spec
        idx = self.command_index.get(command_name)
        if idx is None:
            return None
        physical_range = self.trunk_ranges_deg.get(axis)
        if physical_range is None:
            self._warn_once(
                f"trunk:{axis}",
                f"ignoring {channel!r}: trunk_{axis}_range_deg is missing from policy metadata",
            )
            return None

        physical_offset_deg = float(value_deg) * float(authored_to_physical_sign)
        current_physical_deg = _zero_centered_command_to_physical(
            float(zero_command),
            physical_range,
            self.command_range(command_name),
        )
        target_physical_deg = _clamp(
            current_physical_deg + physical_offset_deg,
            physical_range[0],
            physical_range[1],
        )
        command = _zero_centered_map(
            target_physical_deg,
            physical_range,
            self.command_range(command_name),
        )
        return idx, command, target_physical_deg - current_physical_deg

    def fit_trunk_offset_to_range(
        self,
        channel: str,
        value_deg: float,
        authored_range_deg: Tuple[float, float],
    ) -> float:
        """Scale one authored trunk channel so its extrema use policy limits.

        Positive and negative sides are fitted independently.  This matters for
        clips such as ``shake_it_off`` whose authored extrema are asymmetric
        (+14.17/-12.448 degrees) even though the target policy yaw range is
        symmetric.  The result remains in the authored channel coordinate
        system; :meth:`map_trunk_offset_deg_with_applied` performs the configured
        authored-to-physical sign transform afterward.
        """
        spec = self.trunk_channels.get(channel)
        if spec is None:
            return float(value_deg)
        _command_name, axis, authored_to_physical_sign = spec
        physical_range = self.trunk_ranges_deg.get(axis)
        if physical_range is None:
            return float(value_deg)

        try:
            sign = float(authored_to_physical_sign)
            source_lo = float(authored_range_deg[0])
            source_hi = float(authored_range_deg[1])
            raw_physical = float(value_deg) * sign
        except (TypeError, ValueError, IndexError):
            return float(value_deg)
        if abs(sign) <= 1e-12:
            return 0.0

        source_physical_a = source_lo * sign
        source_physical_b = source_hi * sign
        source_physical_lo = min(source_physical_a, source_physical_b)
        source_physical_hi = max(source_physical_a, source_physical_b)
        target_lo, target_hi = physical_range

        fitted_physical = raw_physical
        if raw_physical > 0.0 and source_physical_hi > 1e-12 and target_hi > 0.0:
            fitted_physical = raw_physical * (float(target_hi) / source_physical_hi)
        elif raw_physical < 0.0 and source_physical_lo < -1e-12 and target_lo < 0.0:
            fitted_physical = raw_physical * (abs(float(target_lo)) / abs(source_physical_lo))

        fitted_physical = _clamp(fitted_physical, target_lo, target_hi)
        return fitted_physical / sign

    def map_joint_offset_deg(
        self,
        name: str,
        offset_deg: float,
        *,
        zero_command: float = 0.0,
    ) -> Optional[Tuple[int, float]]:
        """Add a physical degree offset to a live head/neck command pose."""
        idx = self.command_index.get(name)
        if idx is None:
            return None
        neutral = self.joint_neutral_rad.get(name)
        limits = self.joint_limits_rad.get(name)
        if neutral is None or limits is None:
            self._warn_once(
                f"joint:{name}",
                f"ignoring {name!r}: initial pose or joint limits are missing from policy metadata",
            )
            return None

        current_rad = _zero_centered_command_to_absolute(
            float(zero_command),
            neutral,
            limits,
            self.command_range(name),
        )
        target_rad = current_rad + math.radians(float(offset_deg))
        command = _absolute_to_zero_centered_command(
            target_rad,
            neutral,
            limits,
            self.command_range(name),
        )
        return idx, command

    def map_height_cm(
        self,
        value_cm: float,
        *,
        zero_command: float,
        positive_means_lower: bool = True,
    ) -> Optional[Tuple[int, float]]:
        idx = self.command_index.get("height")
        if idx is None:
            return None
        if self.height_cm_per_command_unit is None or self.height_cm_per_command_unit <= 1e-12:
            self._warn_once(
                "height-scale",
                "ignoring body_height: no physical height span was found; set duckdrive.emote_height_range_cm",
            )
            return None

        sign = -1.0 if positive_means_lower else +1.0
        delta_command = sign * float(value_cm) / float(self.height_cm_per_command_unit)
        lo, hi = self.command_range("height")
        return idx, _clamp(float(zero_command) + delta_command, lo, hi)


class EmotePlayer:
    """Discover, trigger, and sample one named one-shot emote at a time."""

    def __init__(
        self,
        *,
        policy: Any,
        search_dirs: Sequence[str | Path],
        height_range_cm: Optional[float] = None,
        trunk_channel_signs: Optional[Mapping[str, float]] = None,
        interpolate: bool = True,
        suppress_walk_in_place_for_feet_planted: Optional[bool] = None,
        # Deprecated compatibility for the first bundle.  It now controls only
        # the separate walk-in-place/march channel; X/Y/yaw always pass through.
        zero_base_for_feet_planted: Optional[bool] = None,
        debug: bool = False,
    ):
        self.policy = policy
        self.debug = bool(debug)
        self.interpolate = bool(interpolate)
        if suppress_walk_in_place_for_feet_planted is None:
            if zero_base_for_feet_planted is None:
                suppress_walk_in_place_for_feet_planted = True
            else:
                suppress_walk_in_place_for_feet_planted = bool(zero_base_for_feet_planted)
        self.suppress_walk_in_place_for_feet_planted = bool(
            suppress_walk_in_place_for_feet_planted
        )
        self.search_dirs = self._normalize_dirs(search_dirs)
        self.mapper = PolicyCommandMapper(
            policy,
            height_range_cm=height_range_cm,
            trunk_channel_signs=trunk_channel_signs,
            debug=debug,
        )

        self.clips: Dict[str, EmoteClip] = {}
        self.load_errors: Dict[str, str] = {}

        self._active: Optional[EmoteClip] = None
        self._start_t = 0.0
        # Backward-compatible fallback command pose. DuckDrive supplies the
        # freshly synthesized joystick command vector to every sample, so this
        # trigger snapshot is used only by older/direct callers that omit it.
        self._trigger_fallback_commands: Dict[int, float] = {}
        self._last_frame_index = -1

        self.reload()

    @staticmethod
    def _normalize_dirs(values: Sequence[str | Path]) -> Tuple[Path, ...]:
        out = []
        seen = set()
        for raw in values:
            if raw is None:
                continue
            text = os.path.expandvars(os.path.expanduser(str(raw)))
            if not text:
                continue
            path = Path(text).resolve()
            key = str(path)
            if key in seen:
                continue
            seen.add(key)
            out.append(path)
        return tuple(out)

    @staticmethod
    def _load_clip(path: Path) -> Optional[EmoteClip]:
        with path.open("r", encoding="utf-8") as handle:
            doc = json.load(handle)
        if not isinstance(doc, Mapping):
            raise ValueError("JSON root must be an object")
        if str(doc.get("format", "")) != SUPPORTED_FORMAT:
            return None

        name = str(doc.get("name", "")).strip()
        if not name:
            raise ValueError("missing non-empty name")

        try:
            rate_hz = float(doc.get("rate_hz"))
        except (TypeError, ValueError) as exc:
            raise ValueError("rate_hz must be numeric") from exc
        if not math.isfinite(rate_hz) or rate_hz <= 0.0:
            raise ValueError("rate_hz must be > 0")

        raw_channels = doc.get("channels")
        if not isinstance(raw_channels, Sequence) or isinstance(raw_channels, (str, bytes, bytearray)):
            raise ValueError("channels must be a list")
        channels = tuple(str(x) for x in raw_channels)
        if not channels or len(set(channels)) != len(channels):
            raise ValueError("channels must be non-empty and unique")

        raw_frames = doc.get("frames")
        if not isinstance(raw_frames, Sequence) or isinstance(raw_frames, (str, bytes, bytearray)):
            raise ValueError("frames must be a list")
        frames = []
        for frame_index, raw_frame in enumerate(raw_frames):
            if not isinstance(raw_frame, Sequence) or isinstance(raw_frame, (str, bytes, bytearray)):
                raise ValueError(f"frame {frame_index} must be a list")
            if len(raw_frame) != len(channels):
                raise ValueError(
                    f"frame {frame_index} has {len(raw_frame)} values; expected {len(channels)}"
                )
            converted = []
            for channel, raw_value in zip(channels, raw_frame):
                try:
                    value = float(raw_value)
                except (TypeError, ValueError) as exc:
                    raise ValueError(f"frame {frame_index} channel {channel!r} is not numeric") from exc
                if not math.isfinite(value):
                    raise ValueError(f"frame {frame_index} channel {channel!r} is not finite")
                converted.append(value)
            frames.append(tuple(converted))
        if not frames:
            raise ValueError("frames must not be empty")

        declared_duration = doc.get("duration_s")
        if declared_duration is not None:
            try:
                declared_duration = float(declared_duration)
            except (TypeError, ValueError):
                declared_duration = None

        units = doc.get("units") if isinstance(doc.get("units"), Mapping) else {}
        whole_sequence = doc.get("whole_sequence") if isinstance(doc.get("whole_sequence"), Mapping) else {}
        playback = doc.get("playback") if isinstance(doc.get("playback"), Mapping) else {}

        return EmoteClip(
            name=name,
            path=path,
            rate_hz=rate_hz,
            channels=channels,
            frames=tuple(frames),
            units=dict(units),
            whole_sequence=dict(whole_sequence),
            playback=dict(playback),
            declared_duration_s=declared_duration,
        )

    def reload(self) -> Tuple[str, ...]:
        clips: Dict[str, EmoteClip] = {}
        errors: Dict[str, str] = {}

        for directory in self.search_dirs:
            if not directory.is_dir():
                continue
            for path in sorted(directory.glob("*.json")):
                try:
                    clip = self._load_clip(path)
                except Exception as exc:
                    errors[str(path)] = str(exc)
                    if self.debug:
                        print(f"[emote] failed to load {path}: {exc}")
                    continue
                if clip is None:
                    continue
                if clip.name in clips:
                    if self.debug:
                        print(
                            f"[emote] duplicate name {clip.name!r}: keeping {clips[clip.name].path}, "
                            f"ignoring {clip.path}"
                        )
                    continue
                clips[clip.name] = clip

        self.clips = clips
        self.load_errors = errors
        if self.debug and clips:
            names = ", ".join(sorted(clips))
            print(f"[emote] loaded {len(clips)} clip(s): {names}")
        return tuple(sorted(clips))

    def names(self) -> Tuple[str, ...]:
        return tuple(sorted(self.clips))

    def has(self, name: str) -> bool:
        return str(name) in self.clips

    @property
    def active_name(self) -> Optional[str]:
        return self._active.name if self._active is not None else None

    @property
    def active(self) -> bool:
        return self._active is not None

    @property
    def active_feet_planted(self) -> bool:
        return bool(self._active is not None and self._active.feet_planted)

    def _command_zero(
        self,
        name: str,
        current_commands: Optional[Sequence[float]] = None,
    ) -> float:
        """Return the live joystick command used as animation-space zero.

        ``current_commands`` must be the command underlay before this frame's
        animation overlay is applied. DuckDrive guarantees that ordering by
        restoring the previous underlay, synthesizing joystick commands, and
        only then sampling the emote.

        The trigger snapshot remains a compatibility fallback for direct users
        of :class:`EmotePlayer` that have not yet started passing a live command
        vector to :meth:`sample`.
        """
        idx = self.mapper.command_index.get(str(name))
        if idx is None:
            return 0.0
        idx = int(idx)

        if current_commands is not None:
            try:
                if 0 <= idx < len(current_commands):
                    value = float(current_commands[idx])
                    if math.isfinite(value):
                        return value
            except (TypeError, ValueError, IndexError):
                pass

        return float(self._trigger_fallback_commands.get(idx, 0.0))

    def play(
        self,
        name: str,
        *,
        now: float,
        current_commands: Optional[Sequence[float]] = None,
    ) -> bool:
        clip = self.clips.get(str(name))
        if clip is None:
            return False

        self._active = clip
        self._start_t = float(now)
        self._last_frame_index = -1

        self._trigger_fallback_commands = {}
        if current_commands is not None:
            for command_name, raw_idx in self.mapper.command_index.items():
                if command_name in PASSTHROUGH_COMMAND_CHANNELS:
                    continue
                idx = int(raw_idx)
                try:
                    if idx < 0 or idx >= len(current_commands):
                        continue
                    value = float(current_commands[idx])
                except (TypeError, ValueError, IndexError):
                    continue
                if math.isfinite(value):
                    self._trigger_fallback_commands[idx] = value

        if self.debug:
            pose_names = (
                "height",
                "neck_pitch",
                "head_pitch",
                "head_yaw",
                "head_roll",
                "trunk_pitch_cmd",
                "trunk_yaw_cmd",
                "trunk_roll_cmd",
            )
            pose_summary = ", ".join(
                f"{pose_name}={self._command_zero(pose_name):.3f}"
                for pose_name in pose_names
                if pose_name in self.mapper.command_index
            )
            print(
                f"[emote] play {clip.name!r} duration={clip.duration_s:.3f}s "
                f"trigger_fallback[{pose_summary}] live_blend=True"
            )
        return True

    def stop(self) -> Optional[str]:
        name = self.active_name
        self._active = None
        self._trigger_fallback_commands.clear()
        self._last_frame_index = -1
        return name

    def _height_positive_means_lower(self, clip: EmoteClip) -> bool:
        unit = str(clip.units.get("body_height", "")).lower()
        if any(token in unit for token in ("positive = higher", "positive=higher", "positive raises")):
            return False
        if any(token in unit for token in ("squat deeper", "positive = lower", "positive=lower", "positive lowers")):
            return True
        # darkwing_emote_control_v1 convention used by the supplied files.
        return True

    @staticmethod
    def _playback_flag(clip: EmoteClip, name: str, default: bool = False) -> bool:
        raw = clip.playback.get(str(name), default)
        if isinstance(raw, str):
            text = raw.strip().lower()
            if text in ("1", "true", "yes", "on"):
                return True
            if text in ("0", "false", "no", "off", ""):
                return False
        return bool(raw)

    def _feet_planted_zero_commands(self) -> Dict[int, float]:
        """Return only non-joystick gait requests suppressed by feet_planted.

        The first three policy commands (X, Y, yaw) are intentionally absent:
        walking remains live and fully controlled by DuckDrive while the emote
        overlays height, trunk, head, and show channels.
        """
        out: Dict[int, float] = {}
        for name in ("recover", "walk_in_place"):
            idx = self.mapper.command_index.get(name)
            if idx is not None:
                out[int(idx)] = 0.0
        return out

    def sample(
        self,
        *,
        now: float,
        current_commands: Optional[Sequence[float]] = None,
    ) -> Optional[EmoteSample]:
        """Sample the active clip on top of the current joystick pose.

        Passing the live command underlay makes the operator's current pose the
        animation-space zero on every tick. Animation motion therefore remains
        additive while the joystick can continue to contribute throughout the
        one-shot, and completion naturally releases to the latest joystick pose.
        """
        clip = self._active
        if clip is None:
            return None

        elapsed = max(0.0, float(now) - float(self._start_t))
        if elapsed >= clip.duration_s:
            if self.debug:
                print(f"[emote] complete {clip.name!r}")
            self.stop()
            return None

        frame_index, values = clip.sample(elapsed, interpolate=self.interpolate)
        command_values: Dict[int, float] = {}
        show_values: Dict[str, float] = {}

        if clip.feet_planted and self.suppress_walk_in_place_for_feet_planted:
            command_values.update(self._feet_planted_zero_commands())

        positive_height_lowers = self._height_positive_means_lower(clip)

        # Some clips are authored for a narrower source-policy trunk range.
        # ``shake_it_off`` opts into fitting its asymmetric body_twist extrema
        # to this policy's full trunk-yaw degree range.  Its head_yaw channel is
        # an explicit counter-rotation pair, so drive the head from the physical
        # trunk delta that was actually applied after live-pose clamping.
        handled_channels: set[str] = set()
        fit_trunk_yaw = self._playback_flag(
            clip,
            "fit_trunk_yaw_to_range",
            False,
        )
        pair_head_yaw = self._playback_flag(
            clip,
            "pair_head_yaw_with_trunk",
            False,
        )
        if (fit_trunk_yaw or pair_head_yaw) and "body_twist" in clip.channels:
            twist_index = clip.channels.index("body_twist")
            authored_range = clip.channel_range("body_twist")
            if authored_range is not None:
                fitted_twist = float(values[twist_index])
                if fit_trunk_yaw:
                    fitted_twist = self.mapper.fit_trunk_offset_to_range(
                        "body_twist",
                        fitted_twist,
                        authored_range,
                    )
                mapped_twist = self.mapper.map_trunk_offset_deg_with_applied(
                    "body_twist",
                    fitted_twist,
                    zero_command=self._command_zero(
                        "trunk_yaw_cmd",
                        current_commands,
                    ),
                )
                if mapped_twist is not None:
                    command_values[int(mapped_twist[0])] = float(mapped_twist[1])
                    handled_channels.add("body_twist")

                    if pair_head_yaw and "head_yaw" in clip.channels:
                        mapped_head = self.mapper.map_joint_offset_deg(
                            "head_yaw",
                            float(mapped_twist[2]),
                            zero_command=self._command_zero(
                                "head_yaw",
                                current_commands,
                            ),
                        )
                        if mapped_head is not None:
                            command_values[int(mapped_head[0])] = float(mapped_head[1])
                            handled_channels.add("head_yaw")

        for channel, value in zip(clip.channels, values):
            if channel in handled_channels:
                continue

            if channel == "body_height":
                mapped = self.mapper.map_height_cm(
                    value,
                    zero_command=self._command_zero("height", current_commands),
                    positive_means_lower=positive_height_lowers,
                )
                if mapped is not None:
                    command_values[int(mapped[0])] = float(mapped[1])
                continue

            if channel in self.mapper.trunk_channels:
                command_name = self.mapper.trunk_channels[channel][0]
                mapped = self.mapper.map_trunk_offset_deg(
                    channel,
                    value,
                    zero_command=self._command_zero(command_name, current_commands),
                )
                if mapped is not None:
                    command_values[int(mapped[0])] = float(mapped[1])
                continue

            if channel in ABSOLUTE_HEAD_CHANNELS:
                mapped = self.mapper.map_absolute_joint_deg(
                    channel,
                    value,
                    zero_command=self._command_zero(channel, current_commands),
                )
                if mapped is not None:
                    command_values[int(mapped[0])] = float(mapped[1])
                continue

            if channel in SHOW_CHANNELS:
                show_values[channel] = float(value)
                continue

            # Base locomotion is joystick-owned. Ignore these channels even if
            # a future format-compatible file includes normalized values for
            # them; the overlay must never capture or overwrite the live walk.
            if channel in PASSTHROUGH_COMMAND_CHANNELS:
                continue

            # Future format-compatible files may directly name another policy
            # command and declare normalized units for it.
            idx = self.mapper.command_index.get(channel)
            unit = str(clip.units.get(channel, clip.units.get("default", ""))).lower()
            if idx is not None and any(token in unit for token in ("normalized", "unit", "[-1,1]")):
                lo, hi = self.mapper.command_range(channel)
                zero = self._command_zero(channel, current_commands)
                command_values[int(idx)] = _clamp(zero + float(value), lo, hi)

        self._last_frame_index = frame_index
        return EmoteSample(
            name=clip.name,
            frame_index=frame_index,
            elapsed_s=elapsed,
            command_values=command_values,
            show_values=show_values,
            feet_planted=clip.feet_planted,
        )

    def status(self) -> Dict[str, Any]:
        return {
            "active": self.active_name,
            "feet_planted": self.active_feet_planted,
            "available": list(self.names()),
            "search_dirs": [str(path) for path in self.search_dirs],
            "height_range_cm": self.mapper.height_range_cm,
            "height_cm_per_command_unit": self.mapper.height_cm_per_command_unit,
            "pose_relative": True,
            "pose_reference": "live_commands",
            "live_joystick_blend": True,
            # Keep the old status key for compatibility. These are now only
            # fallback values for sample() calls that omit current_commands.
            "pose_zero_commands": {
                name: self._command_zero(name)
                for name in self.mapper.command_index
                if int(self.mapper.command_index[name]) in self._trigger_fallback_commands
            },
            "trigger_fallback_commands": {
                name: self._command_zero(name)
                for name in self.mapper.command_index
                if int(self.mapper.command_index[name]) in self._trigger_fallback_commands
            },
            "passthrough_commands": sorted(PASSTHROUGH_COMMAND_CHANNELS),
            "suppress_walk_in_place_for_feet_planted": (
                self.suppress_walk_in_place_for_feet_planted
            ),
            "trunk_ranges_deg": dict(self.mapper.trunk_ranges_deg),
            "trunk_directions": dict(self.mapper.trunk_directions),
            "active_playback": (
                dict(self._active.playback) if self._active is not None else {}
            ),
            "load_errors": dict(self.load_errors),
        }
